//! Reproduces every value of tools/vectors.json (generated by tools/anydisplay_ref.py vectors).

use anydisplay::proto::crypto::{self, KeyPair};
use anydisplay::proto::frame::{encode_frame, Cipher};
use anydisplay::proto::handshake::{Action, AuthMode, HostHandshake, HostIdentity};
use anydisplay::proto::*;
use serde_json::Value;

const VECTORS: &str = include_str!("../../tools/vectors.json");

fn v() -> Value {
    serde_json::from_str(VECTORS).unwrap()
}

fn hex(s: &Value) -> Vec<u8> {
    let s = s.as_str().unwrap();
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn arr<const N: usize>(s: &Value) -> [u8; N] {
    hex(s).try_into().unwrap()
}

fn seq(start: u8) -> [u8; 32] {
    std::array::from_fn(|i| start + i as u8)
}

#[test]
fn keys_and_ecdh() {
    let v = v();
    let c = KeyPair::from_private(&arr(&v["client_private"])).unwrap();
    let h = KeyPair::from_private(&arr(&v["host_private"])).unwrap();
    assert_eq!(c.public.to_vec(), hex(&v["client_pub"]));
    assert_eq!(h.public.to_vec(), hex(&v["host_pub"]));
    assert_eq!(c.ecdh(&h.public).unwrap().to_vec(), hex(&v["ecdh_z"]));
    assert_eq!(h.ecdh(&c.public).unwrap().to_vec(), hex(&v["ecdh_z"]));
}

#[test]
fn hello_bodies_transcript_and_sas() {
    let v = v();
    let c = KeyPair::from_private(&arr(&v["client_private"])).unwrap();
    let h = KeyPair::from_private(&arr(&v["host_private"])).unwrap();
    let client_nonce: [u8; 32] = arr(&v["client_nonce"]);
    assert_eq!(client_nonce, seq(0));
    let hello_c = HelloC {
        magic: MAGIC,
        major: 1,
        minor: 0,
        device_id: std::array::from_fn(|i| 0xA0 + i as u8),
        device_name: "Phone".into(),
        link: 1,
        auth_required: 1,
        client_pub: c.public,
        client_commit: crypto::sha256(&[&client_nonce]),
    };
    assert_eq!(hello_c.body(), hex(&v["hello_c_body"]));
    let hello_h = HelloH {
        magic: MAGIC,
        major: 1,
        minor: 0,
        host_id: std::array::from_fn(|i| 0xB0 + i as u8),
        host_name: "Mac".into(),
        host_os: "macOS".into(),
        auth_mode: 1,
        host_pub: h.public,
        host_nonce: arr(&v["host_nonce"]),
    };
    assert_eq!(hello_h.body(), hex(&v["hello_h_body"]));
    let reveal = Reveal { client_nonce };
    assert_eq!(reveal.body(), hex(&v["reveal_body"]));
    let t = crypto::sha256(&[&hello_c.body(), &hello_h.body(), &reveal.body()]);
    assert_eq!(t.to_vec(), hex(&v["transcript"]));
    assert_eq!(
        crypto::format_sas(crypto::sas_code(&t)),
        v["sas"].as_str().unwrap()
    );
}

#[test]
fn key_schedule_macs_and_encrypted_ping() {
    let v = v();
    let z: [u8; 32] = arr(&v["ecdh_z"]);
    let t: [u8; 32] = arr(&v["transcript"]);
    let ping = Ping {
        seq: 7,
        sender_time_us: 123_456_789,
    };
    assert_eq!(ping.body(), hex(&v["ping_plaintext_body"]));
    for mode in ["mode1", "mode2"] {
        let m = &v[mode];
        let keys = crypto::key_schedule(&z, &hex(&m["psk"]), &t);
        assert_eq!(keys.k_h2c.to_vec(), hex(&m["k_h2c"]), "{mode} k_h2c");
        assert_eq!(keys.k_c2h.to_vec(), hex(&m["k_c2h"]), "{mode} k_c2h");
        assert_eq!(
            keys.k_confirm.to_vec(),
            hex(&m["k_confirm"]),
            "{mode} k_confirm"
        );
        let auth_h = crypto::confirm_mac(&keys.k_confirm, b"host", &t);
        let auth_c = crypto::confirm_mac(&keys.k_confirm, b"client", &t);
        assert_eq!(auth_h.to_vec(), hex(&m["auth_h"]), "{mode} auth_h");
        assert_eq!(auth_c.to_vec(), hex(&m["auth_c"]), "{mode} auth_c");
        assert!(crypto::verify_confirm_mac(
            &keys.k_confirm,
            b"client",
            &t,
            &auth_c
        ));
        assert!(!crypto::verify_confirm_mac(
            &keys.k_confirm,
            b"client",
            &t,
            &auth_h
        ));
        let wire = encode_frame(&ping.frame(), Some(&mut Cipher::new(&keys.k_h2c)));
        assert_eq!(
            wire[6..].to_vec(),
            hex(&m["encrypted_ping_h2c_seq0"]),
            "{mode} ciphertext"
        );
        assert_eq!(
            &wire[..6],
            &[(2 + 12 + 16) as u8, 0, 0, 0, channel::CONTROL, ty::PING]
        );
    }
}

/// Drives the host state machine with the vector client's messages: HELLO_H, the SAS code,
/// AUTH_H and the session keys must all match the reference values byte for byte.
#[test]
fn host_state_machine_reproduces_mode1_vectors() {
    let v = v();
    let identity = HostIdentity {
        host_id: std::array::from_fn(|i| 0xB0 + i as u8),
        host_name: "Mac".into(),
        host_os: "macOS".into(),
    };
    let key = KeyPair::from_private(&arr(&v["host_private"])).unwrap();
    let mut hs = HostHandshake::with_key(identity, key, arr(&v["host_nonce"]), |_| None);
    let frame = |t: u8, body: Vec<u8>| Frame {
        channel: channel::CONTROL,
        ty: t,
        body,
    };

    let out = hs.receive(&frame(ty::HELLO_C, hex(&v["hello_c_body"])));
    let [Action::Send(hello_h)] = &out[..] else {
        panic!("{out:?}")
    };
    assert_eq!(hello_h.ty, ty::HELLO_H);
    assert_eq!(hello_h.body, hex(&v["hello_h_body"]));

    let out = hs.receive(&frame(ty::REVEAL, hex(&v["reveal_body"])));
    let [Action::ShowSas(code)] = &out[..] else {
        panic!("{out:?}")
    };
    assert_eq!(code, v["sas"].as_str().unwrap());
    assert_eq!(hs.step_timeout().as_secs(), 120);

    // Client confirms first, then the user.
    assert!(hs.receive(&frame(ty::SAS_OK, vec![])).is_empty());
    let out = hs.user_decision(true);
    let [Action::Send(sas_ok), Action::Send(auth_h)] = &out[..] else {
        panic!("{out:?}")
    };
    assert_eq!((sas_ok.ty, sas_ok.body.len()), (ty::SAS_OK, 0));
    assert_eq!(auth_h.ty, ty::AUTH_H);
    assert_eq!(auth_h.body, hex(&v["mode1"]["auth_h"]));

    let out = hs.receive(&frame(ty::AUTH_C, hex(&v["mode1"]["auth_c"])));
    let [Action::EnableEncryption { send, recv }] = &out[..] else {
        panic!("{out:?}")
    };
    assert_eq!(send.to_vec(), hex(&v["mode1"]["k_h2c"]));
    assert_eq!(recv.to_vec(), hex(&v["mode1"]["k_c2h"]));

    let out = hs.receive(&frame(ty::PAIR, vec![0x77; 32]));
    let [Action::Complete(r)] = &out[..] else {
        panic!("{out:?}")
    };
    assert_eq!(r.mode, AuthMode::Sas);
    assert_eq!(r.device_name, "Phone");
    assert_eq!(r.link, 1);
    assert_eq!(r.pair_secret, Some([0x77; 32]));
    assert_eq!(r.transcript.to_vec(), hex(&v["transcript"]));
}

#[test]
fn host_rejects_bad_commit_and_bad_mac() {
    let v = v();
    let identity = HostIdentity {
        host_id: [0; 16],
        host_name: "h".into(),
        host_os: "o".into(),
    };
    let frame = |t: u8, body: Vec<u8>| Frame {
        channel: channel::CONTROL,
        ty: t,
        body,
    };

    let mut hs = HostHandshake::new(identity.clone(), |_| None);
    hs.receive(&frame(ty::HELLO_C, hex(&v["hello_c_body"])));
    let out = hs.receive(&frame(ty::REVEAL, vec![0xEE; 32]));
    assert!(
        matches!(&out[..], [Action::Send(f), Action::Fail(_)] if f.ty == ty::AUTH_FAIL && f.body == [7])
    );

    // The vectors' HELLO_C asks for auth, so a stored secret gives mode 2; a wrong AUTH_C is bad_mac.
    let mut hs = HostHandshake::new(identity.clone(), |_| Some([0x5A; 32]));
    let out = hs.receive(&frame(ty::HELLO_C, hex(&v["hello_c_body"])));
    let [Action::Send(h)] = &out[..] else {
        panic!()
    };
    assert_eq!(HelloH::from_body(&h.body).unwrap().auth_mode, 2);
    let out = hs.receive(&frame(ty::REVEAL, hex(&v["reveal_body"])));
    assert!(matches!(&out[..], [Action::Send(f)] if f.ty == ty::AUTH_H));
    let out = hs.receive(&frame(ty::AUTH_C, vec![0; 32]));
    assert!(matches!(&out[..], [Action::Send(f), Action::Fail(_)] if f.body == [4]));

    // Wrong major.
    let mut body = hex(&v["hello_c_body"]);
    body[4] = 2;
    let mut hs = HostHandshake::new(identity, |_| None);
    let out = hs.receive(&frame(ty::HELLO_C, body));
    assert!(matches!(&out[..], [Action::Send(f), Action::Fail(_)] if f.body == [1]));
}
